export const controlLabels=Object.freeze({forward:'Đi tới',backward:'Đi lui',left:'Sang trái',right:'Sang phải',jump:'Nhảy',dash:'Lướt',interact:'Tương tác',pulse:'Tỏa sáng',pause:'Tạm dừng'});
export const defaultControls=Object.freeze({forward:'KeyW',backward:'KeyS',left:'KeyA',right:'KeyD',jump:'Space',dash:'ShiftLeft',interact:'KeyE',pulse:'KeyQ',pause:'KeyP'});
export const controlActions=Object.freeze(Object.keys(defaultControls));
export function validControlCode(code){return typeof code==='string'&&/^(?:Key[A-Z]|Digit[0-9]|Arrow(?:Up|Down|Left|Right)|Numpad[0-9]|F(?:[1-9]|1[0-2])|Space|Shift(?:Left|Right)|Control(?:Left|Right)|Alt(?:Left|Right)|Bracket(?:Left|Right)|Semicolon|Quote|Comma|Period|Slash|Backslash|Backquote|Minus|Equal)$/.test(code);}
export function normalizeControls(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))return{...defaultControls};const result={...defaultControls};for(const action of controlActions){if(validControlCode(raw[action]))result[action]=raw[action];}return new Set(Object.values(result)).size===controlActions.length?result:{...defaultControls};}
export function remapControl(controls,action,code){if(!Object.hasOwn(defaultControls,action))return{ok:false,error:'Hành động không hợp lệ'};if(!validControlCode(code))return{ok:false,error:'Phím này không hỗ trợ. Nhấn Esc để hủy.'};const conflict=controlActions.find(a=>a!==action&&controls[a]===code);if(conflict)return{ok:false,error:`${code} đã dùng cho ${controlLabels[conflict]}`};return{ok:true,controls:{...controls,[action]:code}};}
export function mappedInput(keys,pressed,controls,yaw=0){const x=+keys.has(controls.right)-+keys.has(controls.left),z=+keys.has(controls.forward)-+keys.has(controls.backward);return{moveX:x*Math.cos(yaw)+z*Math.sin(yaw),moveZ:z*Math.cos(yaw)-x*Math.sin(yaw),jump:keys.has(controls.jump)||pressed.has(controls.jump),dash:pressed.has(controls.dash),interact:pressed.has(controls.interact),pulse:pressed.has(controls.pulse),pause:pressed.has(controls.pause)||pressed.has('Escape')};}
export function normalizeAccessibility(raw){return{controls:normalizeControls(raw?.controls),reducedMotion:raw?.reducedMotion===true,largeText:raw?.largeText===true};}
